    public function getSourceContext(): Source
    {
        return new Source("{% extends 'front/layout.html.twig' %}

{% block title %}Reset Password{% endblock %}

{% block body %}
<section class=\"section\">
    <div class=\"container\">
        <div class=\"row justify-content-center\">
            <div class=\"col-lg-6\">
                <div class=\"bg-white rounded shadow p-5\">
                    <h2 class=\"mb-4\">Reset Password</h2>

                    {% for message in app.flashes('success') %}
                        <div class=\"alert alert-success\">{{ message }}</div>
                    {% endfor %}

                    {% for message in app.flashes('danger') %}
                        <div class=\"alert alert-danger\">{{ message }}</div>
                    {% endfor %}

                    {{ form_start(form) }}
                        <div class=\"mb-3\">
                            {{ form_label(form.plainPassword) }}
                            {{ form_widget(form.plainPassword, {'attr': {'class': 'form-control'}}) }}
                        </div>

                        <button type=\"submit\" class=\"btn btn-primary w-100\">
                            Update password
                        </button>
                    {{ form_end(form) }}
                </div>
            </div>
        </div>
    </div>
</section>
{% endblock %}", "security/reset_password.html.twig", "C:\\Users\\GIGABYTE\\Downloads\\Esprit-PiWeb-3A27-Findinari-dev_ahmed\\Esprit-PiWeb-3A27-Findinari-dev_ahmed\\templates\\security\\reset_password.html.twig");
